"""Original underdark monsters: caverns, fungus forests, lightless lakes, and the deep roads."""
from monster_engine import M
R = lambda **k: "; ".join(f"<b>{a}</b> {b}" for a, b in k.items())
UNDEAD = "Charmed, Exhaustion, Frightened, Poisoned"
CONSTRUCT = "Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned"
PLANT = "Blinded, Deafened, Exhaustion"
SWARM_TRAIT = ("Swarm", "The swarm can occupy another creature's space and vice versa, and it can move through any "
               "opening large enough for a Tiny creature. The swarm can't regain Hit Points or gain Temporary Hit Points.")
SWARM = R(Resistances="Bludgeoning, Piercing, Slashing",
          Immunities="Charmed, Frightened, Grappled, Paralyzed, Petrified, Prone, Restrained, Stunned")
SUN = ("Sunlight Sensitivity", "While in sunlight, the creature has Disadvantage on ability checks and attack rolls.")
SPIDER_CLIMB = ("Spider Climb", "The creature can climb difficult surfaces, including along ceilings, without an ability check.")


def legres(n):
    return (f"Legendary Resistance ({n}/Day)", "If the creature fails a saving throw, it can choose to succeed instead.")


